DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.guard_rental_order_refund()'::regprocedure) INTO definition; definition:=replace(definition,'FOR a IN SELECT value FROM jsonb_array_elements(NEW.allocations)',E'IF TG_OP=''UPDATE'' AND EXISTS(SELECT 1 FROM jsonb_array_elements(OLD.allocations) old_item JOIN jsonb_array_elements(NEW.allocations) new_item ON old_item->>''payment_intent''=new_item->>''payment_intent'' WHERE old_item->>''status'' IN (''succeeded'',''failed'',''canceled'') AND old_item->>''status'' IS DISTINCT FROM new_item->>''status'') THEN RAISE EXCEPTION ''Bestätigte Erstattungszuordnung ist endgültig''; END IF;\nFOR a IN SELECT value FROM jsonb_array_elements(NEW.allocations)'); EXECUTE definition; END $$;